package net.hivel.islandsrpg.visual;
import net.hivel.islandsrpg.IslandsRPGPlugin; import net.hivel.islandsrpg.data.PlayerData; import net.hivel.islandsrpg.util.*; import net.md_5.bungee.api.ChatMessageType; import net.md_5.bungee.api.chat.TextComponent; import org.bukkit.entity.Player; import org.bukkit.scheduler.BukkitTask;
public class ActionBarService { private final IslandsRPGPlugin plugin; private BukkitTask task; public ActionBarService(IslandsRPGPlugin p){plugin=p;} public void start(){stop(); if(!plugin.getConfig().getBoolean("actionbar.enabled",true))return; long interval=plugin.getConfig().getLong("actionbar.interval-ticks",40); task=plugin.getServer().getScheduler().runTaskTimer(plugin,()->{for(Player p:plugin.getServer().getOnlinePlayers()){PlayerData d=plugin.data().get(p); String f=plugin.emojis()?plugin.getConfig().getString("actionbar.format"):plugin.getConfig().getString("actionbar.format-no-emojis"); f=f.replace("%level%",String.valueOf(d.level)).replace("%xp%",NumberUtil.format(d.xp)).replace("%required_xp%",NumberUtil.format(plugin.levels().requiredXp(d.level))).replace("%money%",NumberUtil.format(d.money)).replace("%fragments%",NumberUtil.format(d.fragments)); p.spigot().sendMessage(ChatMessageType.ACTION_BAR, TextComponent.fromLegacyText(ColorUtil.color(f)));}},interval,interval);} public void stop(){if(task!=null)task.cancel();} }
